/* Motorización: etiqueta, combustible, cilindrada, CV, años de producción, cambio,
   código de motor, generación(es) a las que pertenece y mes opcional de inicio/fin. */
const EV = (label, fuel, cc, power, from, to, gearbox, code, g, fromM, toM) => {
  const e = { label, fuel, cc, power, from, to, gearbox, g };
  if (code) e.code = code;
  if (fromM) e.fromM = fromM;
  if (toM) e.toM = toM;
  return e;
};
/* Generación: código corto (agrupa carrocerías), nombre, chasis, carrocería y fechas. */
const GEN = (code, name, chassis, body, from, to, fromM, toM) => {
  const g = { code, name, chassis, body, from, to };
  if (fromM) g.fromM = fromM;
  if (toM) g.toM = toM;
  return g;
};

